<?php
session_start();$lock=__DIR__.'/.installed';$msg='';$ok=false;if(file_exists($lock)){http_response_code(403);exit('Kurulum daha önce tamamlandı.');}
if($_SERVER['REQUEST_METHOD']==='POST'){try{$host=trim($_POST['db_host']??'localhost');$name=preg_replace('/[^a-zA-Z0-9_]/','',trim($_POST['db_name']??''));$user=trim($_POST['db_user']??'');$pass=$_POST['db_pass']??'';$au=trim($_POST['admin_user']??'');$ap=$_POST['admin_pass']??'';if(!$name||!$user||!$au||strlen($ap)<12)throw new Exception('Veritabanı bilgileri ve en az 12 karakterlik güçlü admin şifresi gerekli.');$pdo=new PDO("mysql:host=$host;charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$pdo->exec("CREATE DATABASE IF NOT EXISTS `$name` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");$pdo->exec("USE `$name`");foreach(array_filter(array_map('trim',preg_split('/;\s*(?:\r?\n|$)/',file_get_contents(__DIR__.'/db.sql')))) as $q)$pdo->exec($q);$st=$pdo->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)');$st->execute([$au,password_hash($ap,PASSWORD_DEFAULT)]);$seed=json_decode(file_get_contents(__DIR__.'/products-seed.json'),true)?:[];$ins=$pdo->prepare('INSERT INTO products(slug,name,category,price,badge,image_url,stock,active) VALUES(?,?,?,?,?,?,0,1) ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),price=VALUES(price),badge=VALUES(badge),image_url=VALUES(image_url)');foreach($seed as $p)$ins->execute([$p['slug'],$p['name'],$p['category'],$p['price'],$p['badge']??'',$p['image']??'']);$config="<?php\nreturn ".var_export(['db'=>['host'=>$host,'name'=>$name,'user'=>$user,'pass'=>$pass,'charset'=>'utf8mb4'],'app'=>['name'=>'Erdem Boutique','base_url'=>'']],true).";\n";file_put_contents(__DIR__.'/config.php',$config);file_put_contents($lock,date('c'));$ok=true;$msg='Kurulum tamamlandı. install.php artık kilitlendi.';}catch(Throwable $e){$msg='Kurulum hatası: '.$e->getMessage();}}
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Erdem Boutique Kurulum</title><link rel="stylesheet" href="admin/admin.css"></head><body class="admin-login"><div class="login-card"><div class="admin-logo">ERDEM<small>BOUTIQUE</small></div><p>İlk Kurulum</p><?php if($msg):?><div class="notice <?=$ok?'':'bad'?>"><?=htmlspecialchars($msg,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if(!$ok):?><form method="post"><label>MySQL host<input name="db_host" value="localhost" required></label><label>Veritabanı adı<input name="db_name" required></label><label>MySQL kullanıcı<input name="db_user" required></label><label>MySQL şifre<input name="db_pass" type="password"></label><label>Admin kullanıcı adı<input name="admin_user" required></label><label>Admin şifresi<input name="admin_pass" type="password" minlength="12" required></label><button>Kurulumu Başlat</button></form><?php else:?><a class="primary" style="display:block;text-align:center;text-decoration:none" href="admin/">Admin Paneline Git</a><?php endif;?></div></body></html>